package com.elektoryk.scan.printing;
import com.elektoryk.scan.model.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public final class EstimateReceiptBuilder{private EstimateReceiptBuilder(){}public static byte[] build(CommercialPlan p,String project){try{p.recalc();ByteArrayOutputStream o=new ByteArrayOutputStream();o.write(new byte[]{0x1b,0x40});line(o,"ELEKTORYK");line(o,"KOSHTORYS");line(o,project);line(o,"--------------------------------");for(CommercialLine l:p.lines){if(!l.includeInEstimate)continue;line(o,cut(translit(l.name),28));line(o,String.format(Locale.US," %.2f %s x %.2f = %.2f",l.requiredQty,translit(l.unit),l.unitClientPrice,l.clientTotal()));}line(o,"--------------------------------");line(o,String.format(Locale.US,"MATERIALY: %.2f UAH",p.materialClient));line(o,String.format(Locale.US,"ROBOTY:    %.2f UAH",p.laborClient));line(o,String.format(Locale.US,"RAZOM:     %.2f UAH",p.total));line(o,"");line(o,"Pogodzheni pravky zminyuyut koshtorys.");o.write(new byte[]{0x1b,0x64,0x04});return o.toByteArray();}catch(Exception e){throw new RuntimeException(e);}}
 private static void line(ByteArrayOutputStream o,String s)throws Exception{o.write((s+"\n").getBytes(StandardCharsets.US_ASCII));}private static String cut(String s,int n){return s.length()<=n?s:s.substring(0,n);}private static String translit(String s){if(s==null)return "";String[][] m={{"Щ","Shch"},{"щ","shch"},{"Ш","Sh"},{"ш","sh"},{"Ч","Ch"},{"ч","ch"},{"Ж","Zh"},{"ж","zh"},{"Х","Kh"},{"х","kh"},{"Ц","Ts"},{"ц","ts"},{"Ю","Yu"},{"ю","yu"},{"Я","Ya"},{"я","ya"},{"Є","Ye"},{"є","ie"},{"Ї","Yi"},{"ї","i"},{"Й","Y"},{"й","i"},{"А","A"},{"а","a"},{"Б","B"},{"б","b"},{"В","V"},{"в","v"},{"Г","H"},{"г","h"},{"Ґ","G"},{"ґ","g"},{"Д","D"},{"д","d"},{"Е","E"},{"е","e"},{"З","Z"},{"з","z"},{"И","Y"},{"и","y"},{"І","I"},{"і","i"},{"К","K"},{"к","k"},{"Л","L"},{"л","l"},{"М","M"},{"м","m"},{"Н","N"},{"н","n"},{"О","O"},{"о","o"},{"П","P"},{"п","p"},{"Р","R"},{"р","r"},{"С","S"},{"с","s"},{"Т","T"},{"т","t"},{"У","U"},{"у","u"},{"Ф","F"},{"ф","f"},{"Ь",""},{"ь",""},{"’",""},{"'",""}};for(String[] x:m)s=s.replace(x[0],x[1]);return s.replaceAll("[^\\x20-\\x7E]","?");}}
